71	export const workspacesApi = {
72	  list: () => request<Workspace[]>("/workspaces"),
73	  create: (body: { name: string; slug?: string }) =>
74	    request<Workspace>("/workspaces", { method: "POST", body: JSON.stringify(body) }),
75	  detail: (slug: string) => request<WorkspaceDetail>(`/workspaces/${slug}`),
76	  rename: (slug: string, name: string) =>
77	    request<Workspace>(`/workspaces/${slug}`, { method: "PATCH", body: JSON.stringify({ name }) }),
78	  remove: (slug: string) => request<void>(`/workspaces/${slug}`, { method: "DELETE" }),
79	  invite: (slug: string, email: string, role: "member" | "admin" = "member") =>
80	    request<unknown>(`/workspaces/${slug}/members`, {
81	      method: "POST",
82	      body: JSON.stringify({ email, role }),
83	    }),
84	  removeMember: (slug: string, memberId: number) =>
85	    request<void>(`/workspaces/${slug}/members/${memberId}`, { method: "DELETE" }),
86	  createProject: (slug: string, body: { name: string; description?: string; gameType?: string; genre?: string; playerCount?: string; targetDuration?: string }) =>
87	    request<{ project: WorkspaceProject; workspaceSlug: string }>(`/workspaces/${slug}/projects`, {
88	      method: "POST",
89	      body: JSON.stringify(body),
90	    }),
91	  resolveProject: (slug: string, projectSlug: string) =>
92	    request<WorkspaceProject>(`/workspaces/${slug}/projects/${projectSlug}`),
93	  generate: (slug: string, body: { prompt?: string; template?: string }) =>
94	    request<{ project: WorkspaceProject; workspaceSlug: string }>(`/workspaces/${slug}/generate`, {
95	      method: "POST",
96	      body: JSON.stringify(body),
97	    }),
98	  getInviteCode: (slug: string) =>
99	    request<{ inviteCode: string; joinUrl: string }>(`/workspaces/${slug}/invite-code`),
100	  refreshInviteCode: (slug: string) =>
101	    request<{ inviteCode: string; joinUrl: string }>(`/workspaces/${slug}/invite-code/refresh`, { method: "POST" }),
102	  previewJoin: (code: string) =>
103	    request<{ id: number; name: string; slug: string; memberCount: number }>(`/workspaces/join/${code}`),
104	  joinByCode: (code: string) =>
105	    request<{ slug: string; name: string }>(`/workspaces/join/${code}`, { method: "POST" }),
106	  listAiSettings: (slug: string) =>
107	    request<WorkspaceProviderSetting[]>(`/workspaces/${slug}/ai-settings`),
108	  updateAiSetting: (
109	    slug: string,
110	    provider: WorkspaceProviderName,
111	    body: { enabled?: boolean; apiKey?: string | null },
112	  ) =>
113	    request<WorkspaceProviderSetting>(`/workspaces/${slug}/ai-settings/${provider}`, {
114	      method: "PUT",
115	      body: JSON.stringify(body),
116	    }),
117	};
118	
119	export type WorkspaceProviderName = "anthropic" | "openai" | "gemini" | "openrouter";
120	
121	export interface WorkspaceProviderSetting {
122	  provider: WorkspaceProviderName;
123	  enabled: boolean;
124	  hasKey: boolean;
125	}
